    if ((t === T_ASC || t === T_XH) && SKEW_SYM.test(s.label) && h > 0.3 * ref) return { x: (b[0] + b[2]) / 2, y: b[3], h: t === T_XH ? h / 0.62 : h, k: 0 };
    if (SKEW_AXIS.has(s.label)) return { x: (b[0] + b[2]) / 2, y: (b[1] + b[3]) / 2, h: 0, k: 1 };
    return null;
