      if (lab !== null && RELATIONS.has(lab) && !(bb[0] > b[0] + 0.1 * w && bb[2] < b[2] - 0.1 * w)) return false;
      if (u.type === T_OP && lab !== '-' && ((bb[0] + bb[2]) / 2 < b[0] + 0.02 * w || (bb[0] + bb[2]) / 2 > b[2] - 0.02 * w)) return false;
